+
+.section{padding:28px 0}
+.section h2{
+  margin:0 0 14px;
+  font-size:22px;
+  letter-spacing:-.01em;
+}
+.subhead{color:var(--muted); margin:-6px 0 16px; line-height:1.45}
+
+.grid3{display:grid; grid-template-columns:repeat(3,1fr); gap:16px}
