+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap:16px;
+  border-radius:var(--radius);
+  border:1px solid rgba(34,211,238,.20);
+  background:linear-gradient(180deg, rgba(34,211,238,.08), rgba(34,197,94,.04));
+  padding:18px;
+}
