+  display:inline-flex; align-items:center;
+  padding:2px 8px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  color:var(--muted);
+  font-family:var(--code);
+  font-size:12px;
+}
+
+.docs-layout{
+  display:grid;
+  grid-template-columns:280px 1fr;
+  gap:18px;
+  align-items:start;
+  padding:18px 0 40px;
+}
+.sidebar{
+  position:sticky;
+  top:calc(var(--navH) + 16px);
+  border-radius:var(--radius);
+  border:1px solid var(--border);
+  background:linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,.015));
+  padding:14px;
+  max-height:calc(100vh - var(--navH) - 32px);
+  overflow:auto;
+}
+.sidebar h3{margin:0 0 10px; color:var(--muted); font-size:13px; letter-spacing:.02em}
+.side-links{display:flex; flex-direction:column; gap:6px}
+.side-links a{
+  padding:9px 10px;
+  border-radius:10px;
+  border:1px solid rgba(255,255,255,.06);
+  background:rgba(255,255,255,.02);
+  color:var(--muted);
+  font-weight:650;
+}
+.side-links a:hover{color:var(--text); border-color:rgba(255,255,255,.12)}
+.side-links a.active{color:var(--text); border-color:rgba(34,211,238,.35); background:rgba(34,211,238,.06)}
+
+.sidebar-collapsed .docs-layout{grid-template-columns:72px 1fr}
+.sidebar-collapsed .sidebar{padding:10px}
+.sidebar-collapsed .sidebar h3,
+.sidebar-collapsed .sidebar .link-text{display:none}
+.sidebar-collapsed .side-links a{display:flex; justify-content:center}
+
+.doc{
+  border-radius:var(--radius);
+  border:1px solid var(--border);
+  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  padding:22px;
+}
+.doc h1{margin:0 0 10px; font-size:32px; letter-spacing:-.02em}
+.doc h2{margin:22px 0 10px; font-size:20px}
+.doc p{margin:0 0 10px; color:var(--muted); line-height:1.65}
+
+.doc .grid2{display:grid; grid-template-columns:repeat(2,1fr); gap:14px}
+.doc .grid3{grid-template-columns:repeat(3,1fr)}
+.doc .mini{
+  border-radius:var(--radius-sm);
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(255,255,255,.02);
+  padding:14px;
+}
+.doc .mini h3{margin:0 0 6px; font-size:14.5px}
+.doc .mini p{margin:0; color:var(--muted2)}
+
+.foot{
+  border-top:1px solid rgba(255,255,255,.08);
+  padding:28px 0 44px;
+  color:var(--muted);
+}
+.foot-grid{display:grid; grid-template-columns:repeat(4,1fr); gap:16px}
+.foot h4{margin:0 0 10px; color:var(--text); font-size:13px}
+.foot a{display:block; padding:6px 0; color:var(--muted)}
+.foot a:hover{color:var(--text)}
+
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+
+@media (max-width: 960px){
+  .hero-grid{grid-template-columns:1fr}
+  .cli-grid{grid-template-columns:1fr}
+  .grid3{grid-template-columns:1fr}
+  .foot-grid{grid-template-columns:repeat(2,1fr)}
+  .docs-layout{grid-template-columns:1fr}
+  .sidebar{position:relative; top:0; max-height:none}
+}
+
+@media (max-width: 520px){
+  .hero{padding:44px 0 22px}
+  .hero h1{font-size:34px}
+  .foot-grid{grid-template-columns:1fr}
+}
+
*** End Patch
PATCH

